// Confere a leitura do ESP32 e separa os dois sensores.
// Saída 1: dados do Sensor 1 (água) para a API.  Saída 2: alerta do Sensor 2 (tampa).
const l = msg.payload;
if (typeof l !== "object" || l === null || !l.codigoDispositivo) {
    node.warn("Mensagem ignorada: não é uma leitura da Gota Certa");
    node.status({ fill: "yellow", shape: "ring", text: "mensagem inválida" });
    return null;
}
const hora = (l.dataHora || "").slice(11, 16);

// SENSOR 2 · tampa: avisa só quando muda de fechada para aberta (sem repetir)
let alertaTampa = null;
const chave = "tampa_" + l.codigoDispositivo;
const estavaAberta = flow.get(chave) || false;
if (l.tampaAberta === true && !estavaAberta) {
    alertaTampa = { payload: { dispositivo: l.codigoDispositivo, hora,
        alertas: ["TAMPA_VIOLADA"],
        mensagem: `Tampa do dispositivo aberta (${l.luzExternaLux} lux). Possível fraude ou vandalismo.` } };
}
if (typeof l.tampaAberta === "boolean") flow.set(chave, l.tampaAberta);

// SENSOR 1 · água: manda para a API só os campos que ela conhece
const leitura = {
    codigoDispositivo: l.codigoDispositivo,
    dataHora: l.dataHora,
    pulsosRegistrados: l.pulsosRegistrados,
    vazaoInstantaneaLpm: l.vazaoInstantaneaLpm,
    leituraAcumuladaLitros: l.leituraAcumuladaLitros,
    intensidadeLuz: l.intensidadeLuz
};
const base = env.get("API_BASE_URL") || "http://localhost:8080";
msg.payload = leitura;
msg.leitura = leitura;                 // guarda o original para a fila, se a API cair
msg.url = base + "/api/leituras";
msg.method = "POST";
msg.headers = { "Content-Type": "application/json" };
node.status({ fill: l.tampaAberta ? "red" : "blue", shape: "dot",
    text: `${l.codigoDispositivo} ${hora} · ${l.vazaoInstantaneaLpm} L/min` + (l.tampaAberta ? " · TAMPA ABERTA" : "") });
return [msg, alertaTampa];

// Lê a resposta da API. Saída 1: leitura aceita. Saída 2: alerta gerado.
const st = msg.statusCode;
const l = msg.leitura || {};
const hora = (l.dataHora || "").slice(11, 16);
if (typeof st !== "number" || st >= 500) {
    // API fora do ar (ou erro do servidor): guarda e tenta de novo depois
    const fila = flow.get("fila") || [];
    fila.push(l);
    flow.set("fila", fila);
    node.status({ fill: "red", shape: "ring", text: `API fora do ar · ${fila.length} na fila` });
    node.warn(`API indisponível (${st}). Leitura de ${hora} guardada na fila.`);
    return null;
}
if (st >= 400) {
    // Dado errado (400) ou dispositivo não cadastrado (404): repetir não resolve
    node.status({ fill: "yellow", shape: "dot", text: `${st} rejeitada · ${hora}` });
    node.warn(`Leitura rejeitada (${st}): ${JSON.stringify(msg.payload)}`);
    return null;
}
const r = msg.payload || {};
if (r.alertaGerado) {
    const tipos = (r.tiposAlertasGerados || []).join(", ");
    node.status({ fill: "red", shape: "dot", text: `🚨 ${hora} ${tipos}` });
    return [null, { payload: { dispositivo: r.codigoDispositivo, hora, alertas: r.tiposAlertasGerados, mensagem: r.mensagemResumo } }];
}
node.status({ fill: "green", shape: "dot", text: `${st} ok · ${hora} · sem alerta` });
return [msg, null];

// A cada 15 s, se houver leituras guardadas, manda de novo (na ordem).
const fila = flow.get("fila") || [];
if (fila.length === 0) { node.status({}); return null; }
flow.set("fila", []);
node.status({ fill: "blue", shape: "dot", text: `reenviando ${fila.length}` });
return [fila.map(l => ({ payload: l }))];
